<script setup lang="ts">
import{computed,onMounted,ref,watch}from'vue';import{api}from'../api/client'
const facilities=ref<any[]>([]),properties=ref<any[]>([]),propertyID=ref(''),selected=ref<string[]>([]),newName=ref(''),showModal=ref(false),message=ref(''),error=ref('')
const currentProperty=computed(()=>properties.value.find(x=>x.ID===propertyID.value))
async function load(){const[f,p]=await Promise.all([api.get('/facilities'),api.get('/properties',{params:{page:1,page_size:100}})]);facilities.value=f.data.items||[];properties.value=p.data.items||[];if(!propertyID.value&&properties.value.length)propertyID.value=properties.value[0].ID}
async function loadBindings(){if(!propertyID.value){selected.value=[];return}const r=await api.get(`/properties/${propertyID.value}/facilities`);selected.value=(r.data.items||[]).map((x:any)=>x.ID)}
async function createFacility(){error.value='';try{await api.post('/facilities',{name:newName.value});newName.value='';showModal.value=false;await load()}catch(e:any){error.value=e.response?.data?.error?.message||'新增设施失败'}}
async function save(){await api.put(`/properties/${propertyID.value}/facilities`,{facility_ids:selected.value});message.value='设施配置已保存';setTimeout(()=>message.value='',2200)}
watch(propertyID,loadBindings);onMounted(async()=>{await load();await loadBindings()})
</script><template><div class="page"><div class="page-title"><div><h1>房源设施</h1><p>维护设施字典，并为房源配置实际配套设施</p></div><button class="primary-button" @click="showModal=true">＋ 新增设施</button></div><div class="stat-grid"><div class="stat-card"><span>设施类型</span><strong>{{facilities.length}}</strong></div><div class="stat-card"><span>可配置房源</span><strong>{{properties.length}}</strong></div><div class="stat-card"><span>当前已选</span><strong>{{selected.length}}</strong></div><div class="stat-card"><span>配置状态</span><strong style="font-size:18px">{{propertyID?'编辑中':'待选择'}}</strong></div></div><section class="card"><div class="toolbar"><div><h3 style="margin:0 0 6px">选择房源</h3><span style="color:#8793a5;font-size:12px">选择后勾选该房源拥有的设施</span></div><div class="field"><select v-model="propertyID" style="min-width:300px"><option value="">请选择房源</option><option v-for="x in properties" :key="x.ID" :value="x.ID">{{x.Building}} · {{x.Room}}</option></select></div></div><div v-if="currentProperty" class="property-summary"><div class="avatar">房</div><div><strong>{{currentProperty.Building}} {{currentProperty.Room}}</strong><span>当前状态：{{currentProperty.Status}}</span></div></div><div v-if="facilities.length" class="facility-grid"><label v-for="x in facilities" :key="x.ID" class="facility-option" :class="{selected:selected.includes(x.ID)}"><input v-model="selected" type="checkbox" :value="x.ID"><span class="facility-icon">◇</span><strong>{{x.Name}}</strong><small>{{selected.includes(x.ID)?'已配置':'点击选择'}}</small></label></div><div v-else class="empty-state"><b>还没有设施类型</b><span>请先点击“新增设施”创建空调、冰箱、床等设施</span></div><div class="save-bar"><span :class="{'success-text':message}">{{message||`已选择 ${selected.length} 项设施`}}</span><button class="primary-button" :disabled="!propertyID" @click="save">保存房源设施</button></div></section><div v-if="showModal" class="modal-mask" @click.self="showModal=false"><div class="modal" style="width:480px"><div class="modal-header"><div><h3>新增设施类型</h3><small>创建后可配置到任意房源</small></div><button class="close-button" @click="showModal=false">×</button></div><div class="modal-body"><div class="form-grid"><label class="full"><span>设施名称 *</span><input v-model="newName" placeholder="例如：空调、冰箱、独立洗衣机" @keyup.enter="createFacility"></label></div><p v-if="error" class="form-error">{{error}}</p></div><div class="modal-footer"><button class="secondary-button" @click="showModal=false">取消</button><button class="primary-button" :disabled="!newName.trim()" @click="createFacility">确认新增</button></div></div></div></div></template><style scoped>.property-summary{display:flex;align-items:center;gap:12px;background:#f7fafc;border:1px solid #e7edf4;border-radius:11px;padding:13px;margin:16px 0}.property-summary strong,.property-summary span{display:block}.property-summary span{font-size:12px;color:#8894a6;margin-top:5px}.facility-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.facility-option{border:1px solid #dfe6ef;border-radius:12px;padding:15px;position:relative;cursor:pointer;transition:.2s}.facility-option input{position:absolute;right:12px;top:12px}.facility-option strong,.facility-option small{display:block}.facility-option small{color:#929daf;font-size:11px;margin-top:6px}.facility-option.selected{border-color:#31ac92;background:#effaf7;box-shadow:0 0 0 2px rgba(49,172,146,.08)}.facility-icon{display:grid;place-items:center;width:34px;height:34px;background:#eef4fb;color:#2c7db4;border-radius:9px;margin-bottom:10px}.save-bar{border-top:1px solid #e9edf4;padding-top:17px;display:flex;justify-content:space-between;align-items:center;color:#8290a3;font-size:12px}.success-text{color:#169074}</style>